// noteFit.js — estimate how tall a note card must be to show all of its text.
//
// The app clips a note to its stored `h` (fading the bottom), and the API
// server has no DOM, so a note added through /api/v1 or MCP needs an estimate
// of the rendered height. This is a small pure model of the CSS in styles.css
// (`.note`, `.note-body`, headings, lists, `.note-checklist`) fed by measured
// per-character widths (noteFitMetrics.js, generated by
// scripts/measure-note-metrics.mjs). Calibrated against real Chromium
// layout by tests/note-fit.spec.js. Overestimating a little is fine;
// underestimating is the bug this exists to prevent, so the model leans high:
// per-character MAX of Aileron and the system fallback, a 1.03 width headroom
// and `safety` px at the end.
//
// Pure ESM, no DOM, no deps beyond the metrics table (it runs in the Worker).
import { NOTE_EM } from './noteFitMetrics.js';

export const NOTE_FIT = { minH: 72, maxH: 480, width: 280, wideWidth: 320, fontSize: 15, safety: 4 };

// .note: border 1px + padding 14px each side.
const CHROME = 30;
const WIDTH_HEADROOM = 1.03;
const BODY = { size: 15, lh: 22.5, ls: -0.002, bold: false };
const HEADING = {
  h1: { size: 15 * 1.35 },
  h2: { size: 15 * 1.18 },
  h3: { size: 15 * 1.05 },
};
const BOLD_LINE_EXTRA = 1;
const LIST_INDENT = 24; // ul:not(.note-checklist), ol: padding-left
const CK_INDENT = 14 + 8; // .ck-box width + .ck gap

const INLINE = new Set([
  'strong', 'b', 'em', 'i', 'a', 'span', 'u', 's', 'strike', 'del', 'ins', 'mark', 'code',
  'small', 'sub', 'sup', 'font', 'abbr', 'cite', 'q', 'kbd', 'var', 'time', 'label', 'big',
]);
const VOID = new Set(['br', 'hr', 'img', 'input', 'wbr', 'meta', 'link']);
const SKIP_CONTENT = new Set(['script', 'style', 'head', 'title']);

// ---------------------------------------------------------------------------
// Parsing

const NAMED = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ' };

function decodeEntities(s) {
  if (s.indexOf('&') < 0) return s;
  return s.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (m, e) => {
    if (e[0] === '#') {
      const cp = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      if (!Number.isFinite(cp) || cp < 0 || cp > 0x10ffff) return m;
      return String.fromCodePoint(cp);
    }
    const v = NAMED[e.toLowerCase()];
    return v === undefined ? m : v;
  });
}

const TAG_RE = /<!--[\s\S]*?-->|<(\/?)([a-zA-Z][a-zA-Z0-9-]*)((?:"[^"]*"|'[^']*'|[^>"'])*)>|[^<]+|</g;

function classOf(attrs) {
  const m = /class\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i.exec(attrs || '');
  return m ? ' ' + (m[1] ?? m[2] ?? m[3] ?? '') + ' ' : '';
}
const hasClass = (node, c) => node.cls.indexOf(' ' + c + ' ') >= 0;

// -> { tag:'#body', children:[ element | {text,bold} | {br:true} ] }
export function parseNoteHtml(html) {
  const root = { tag: '#body', cls: '', children: [] };
  const src = typeof html === 'string' ? html : '';
  if (!/<\/?[a-zA-Z]/.test(src)) {
    // No tags: one paragraph per line.
    for (const line of decodeEntities(src).split('\n')) {
      const p = { tag: 'p', cls: '', children: [] };
      if (line) p.children.push({ text: line, bold: false });
      root.children.push(p);
    }
    return root;
  }
  const stack = [root];
  let bold = 0;
  let skipping = null;
  const top = () => stack[stack.length - 1];
  let m;
  TAG_RE.lastIndex = 0;
  while ((m = TAG_RE.exec(src))) {
    const [tok, close, rawName, attrs] = m;
    if (!rawName) {
      if (skipping || tok[0] === '<' && tok.length > 1) continue; // comment
      if (tok === '<') { top().children.push({ text: '<', bold: bold > 0 }); continue; }
      top().children.push({ text: decodeEntities(tok), bold: bold > 0 });
      continue;
    }
    const name = rawName.toLowerCase();
    if (skipping) { if (close && name === skipping) skipping = null; continue; }
    if (!close && SKIP_CONTENT.has(name)) { skipping = name; continue; }
    if (name === 'strong' || name === 'b') { bold = Math.max(0, bold + (close ? -1 : 1)); continue; }
    if (name === 'br') { if (!close) top().children.push({ br: true }); continue; }
    if (INLINE.has(name) || VOID.has(name)) continue;
    if (close) {
      for (let i = stack.length - 1; i > 0; i--) {
        if (stack[i].tag === name) { stack.length = i; break; }
      }
      continue;
    }
    // A block opening inside a paragraph or heading closes it.
    while (stack.length > 1 && /^(p|h[1-3])$/.test(top().tag)) stack.pop();
    if (name === 'li') {
      for (let i = stack.length - 1; i > 0; i--) {
        if (stack[i].tag === 'ul' || stack[i].tag === 'ol') { stack.length = i + 1; break; }
        if (stack[i].tag === 'li') { /* nested content stays */ }
      }
    }
    const node = { tag: name, cls: classOf(attrs), children: [] };
    top().children.push(node);
    if (!/\/\s*$/.test(attrs || '')) stack.push(node);
  }
  return root;
}

// ---------------------------------------------------------------------------
// Text measuring and wrapping

const isElement = (n) => !!n.tag;
const isBlockEl = (n) => isElement(n); // inline tags are never kept as nodes

function advance(ch, bold, size, ls) {
  const t = bold ? NOTE_EM.bold : NOTE_EM.regular;
  const cp = ch.codePointAt(0);
  let em = t[ch === ' ' || ch === '\t' ? ' ' : ch];
  if (em === undefined) em = cp >= 0x1100 ? NOTE_EM.wide : bold ? NOTE_EM.unknownBold : NOTE_EM.unknownRegular;
  return (em * WIDTH_HEADROOM + ls) * size;
}
const BREAK_AFTER = '-?\u2013\u2014';
const isWideCh = (ch) => ch.codePointAt(0) >= 0x1100 && !(ch in NOTE_EM.regular);

// Number of lines a run of text/br nodes takes in `width` px.
function countLines(run, width, ctx, boldRun = { v: false }) {
  const segs = [[]];
  for (const n of run) {
    if (n.br) { segs.push([]); continue; }
    const bold = ctx.bold || n.bold;
    if (n.bold && /\S/.test(n.text)) boldRun.v = true;
    for (const ch of n.text) {
      if (ch === '\n') segs.push([]);
      else segs[segs.length - 1].push({ ch, w: advance(ch, bold, ctx.size, ctx.ls) });
    }
  }
  if (segs.length > 1 && segs[segs.length - 1].length === 0) segs.pop(); // trailing <br> adds no line
  let lines = 0;
  for (const seg of segs) lines += wrapLine(seg, width);
  return Math.max(1, lines);
}

function wrapLine(chars, avail) {
  let lines = 1;
  let x = 0;
  let i = 0;
  const n = chars.length;
  // Chrome also breaks after a hyphen or question mark (UAX #14; measured: not after a slash), unless
  // a digit follows; a break there can leave a gap that a plain character
  // break would not, so a long URL takes more lines than if it packed tightly.
  const placeWord = (parts) => {
    let seg = [];
    let sw = 0;
    for (let k = 0; k < parts.length; k++) {
      seg.push(parts[k]); sw += parts[k].w;
      const next = parts[k + 1];
      if (next && BREAK_AFTER.includes(parts[k].ch) && !/[0-9]/.test(next.ch)) { place(sw, seg); seg = []; sw = 0; }
    }
    if (seg.length) place(sw, seg);
  };
  const place = (ww, parts) => {
    if (x + ww <= avail) { x += ww; return; }
    if (x > 0) { lines++; x = 0; }
    if (ww <= avail) { x = ww; return; }
    for (const c of parts) { // overflow-wrap: anywhere
      if (x + c.w > avail && x > 0) { lines++; x = 0; }
      x += c.w;
    }
  };
  while (i < n) {
    const c = chars[i];
    if (c.ch === ' ' || c.ch === '\t') { x += c.w; i++; continue; } // spaces hang (pre-wrap)
    if (isWideCh(c.ch)) { place(c.w, [c]); i++; continue; }
    const parts = [];
    let ww = 0;
    while (i < n && chars[i].ch !== ' ' && chars[i].ch !== '\t' && !isWideCh(chars[i].ch)) {
      parts.push(chars[i]); ww += chars[i].w; i++;
    }
    if (parts.length > 1) placeWord(parts); else place(ww, parts);
  }
  return lines;
}

// ---------------------------------------------------------------------------
// Layout: every box is { h, mt, mb } — content height and the margins that may
// still collapse with a neighbour. Margins collapse between siblings
// (max) and through a parent that has no padding/border.

function layoutChildren(children, width, ctx, bodyTop) {
  const hasBlock = children.some(isBlockEl);
  const items = [];
  let run = [];
  const flush = () => {
    if (!run.length) return;
    const blank = run.every((n) => !n.br && !/\S/.test(n.text));
    if (!(hasBlock && blank)) {
      const br = { v: false };
      const lines = countLines(run, width, ctx, br);
      // A <strong> in a regular line brings its own font's ascent/descent into
      // the line box: measured ~1px taller per line with Aileron 700.
      items.push({ h: lines * (ctx.lh + (br.v && !ctx.bold ? BOLD_LINE_EXTRA : 0)), mt: 0, mb: 0 });
    }
    run = [];
  };
  for (const n of children) {
    if (isBlockEl(n)) {
      flush();
      items.push(layoutBlock(n, width, ctx, bodyTop && items.length === 0));
    } else run.push(n);
  }
  flush();
  if (!items.length) {
    // An empty block still has one line (p:empty::before, the editor's <br>).
    return { h: ctx.lh, mt: 0, mb: 0 };
  }
  let h = items[0].h;
  for (let i = 1; i < items.length; i++) {
    h += Math.max(items[i - 1].mb, items[i].mt) + items[i].h;
  }
  return { h, mt: items[0].mt, mb: items[items.length - 1].mb };
}

function layoutBlock(node, width, ctx, firstInBody) {
  const tag = node.tag;
  if (/^h[1-3]$/.test(tag)) {
    const size = HEADING[tag].size;
    const hctx = { size, lh: size * 1.25, ls: -0.012, bold: true };
    const inner = layoutChildren(node.children, width, hctx, false);
    return { h: inner.h, mt: firstInBody ? 0 : Math.max(0.5 * size, inner.mt), mb: Math.max(0.2 * size, inner.mb) };
  }
  if (tag === 'ul' || tag === 'ol') {
    const checklist = hasClass(node, 'note-checklist');
    const inner = layoutChildren(node.children, width - (checklist ? 0 : LIST_INDENT), ctx, false);
    return { h: inner.h, mt: Math.max(6, inner.mt), mb: Math.max(6, inner.mb) };
  }
  if (tag === 'li' && hasClass(node, 'ck')) {
    const w = width - CK_INDENT;
    const textEl = node.children.find((c) => isElement(c) && hasClass(c, 'ck-text'));
    const body = textEl || { tag: 'div', cls: '', children: node.children.filter((c) => !(isElement(c) && hasClass(c, 'ck-box'))) };
    const inner = layoutBlock(body, w, ctx, false);
    // .ck has padding 2px 0, and its flex item contains its children's margins.
    return { h: inner.mt + inner.h + inner.mb + 4, mt: 0, mb: 0 };
  }
  const inner = layoutChildren(node.children, width, ctx, false);
  if (tag === 'li') return { h: inner.h, mt: Math.max(2, inner.mt), mb: Math.max(2, inner.mb) };
  return inner; // p, div and any unknown block: margin 0
}

// Full .note height (chrome included) at card width w, unclamped.
export function noteContentHeight(html, w) {
  const root = parseNoteHtml(html);
  // .note-body is a flex item: its first/last child's margins stay inside it.
  const inner = layoutChildren(root.children, w - CHROME, BODY, true);
  return CHROME + inner.mt + inner.h + inner.mb;
}

export function fitNoteSize({ html, w, h } = {}) {
  const hasW = Number.isFinite(w) && w > 0;
  if (Number.isFinite(h) && h > 0) return { w: hasW ? w : NOTE_FIT.width, h: Math.round(h), overflow: false };
  const blank = typeof html !== 'string' || html.trim() === '';
  const clamp = (c) => Math.min(NOTE_FIT.maxH, Math.max(NOTE_FIT.minH, Math.ceil(c + NOTE_FIT.safety)));
  if (hasW) {
    if (blank) return { w, h: NOTE_FIT.minH, overflow: false };
    const c = noteContentHeight(html, w);
    return { w, h: clamp(c), overflow: c > NOTE_FIT.maxH };
  }
  if (blank) return { w: NOTE_FIT.width, h: NOTE_FIT.minH, overflow: false };
  let width = NOTE_FIT.width;
  let c = noteContentHeight(html, width);
  if (c > NOTE_FIT.maxH) { width = NOTE_FIT.wideWidth; c = noteContentHeight(html, width); }
  return { w: width, h: clamp(c), overflow: c > NOTE_FIT.maxH };
}
